-- =================================================================
-- 1. CREATE TABLES (IF NOT EXIST) & POPULATE CELL GROUPS & CELLS
-- =================================================================
BEGIN;

CREATE TABLE IF NOT EXISTS public.cell_groups (
  id UUID PRIMARY KEY,
  church_id UUID,
  name TEXT NOT NULL,
  group_name TEXT NOT NULL,
  total_cells INTEGER DEFAULT 0,
  total_members INTEGER DEFAULT 0,
  status TEXT DEFAULT 'Active',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.cells (
  id UUID PRIMARY KEY,
  cell_group_id UUID,
  cell_group_name TEXT,
  church_id UUID,
  name TEXT NOT NULL,
  cell_name TEXT NOT NULL,
  raw_name TEXT,
  member_count INTEGER DEFAULT 0,
  meeting_day TEXT DEFAULT 'Wednesday',
  meeting_time TEXT DEFAULT '18:00',
  meeting_location TEXT DEFAULT 'Maputo Central',
  status TEXT DEFAULT 'Active',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Permissions and RLS
GRANT ALL ON public.cell_groups TO public;
GRANT ALL ON public.cells TO public;

ALTER TABLE public.cell_groups ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow read cell_groups" ON public.cell_groups;
CREATE POLICY "Allow read cell_groups" ON public.cell_groups FOR SELECT TO public USING (true);
DROP POLICY IF EXISTS "Allow all cell_groups admin" ON public.cell_groups;
CREATE POLICY "Allow all cell_groups admin" ON public.cell_groups FOR ALL TO public USING (true) WITH CHECK (true);

ALTER TABLE public.cells ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow read cells" ON public.cells;
CREATE POLICY "Allow read cells" ON public.cells FOR SELECT TO public USING (true);
DROP POLICY IF EXISTS "Allow all cells admin" ON public.cells;
CREATE POLICY "Allow all cells admin" ON public.cells FOR ALL TO public USING (true) WITH CHECK (true);

-- Clean previous rows
DELETE FROM public.cells;
DELETE FROM public.cell_groups;

-- Insert 17 Cell Groups

-- Insert 176 Cells

COMMIT;
